// All app-level AndroidManifest.xml changes live here. android/ is generated by
// `expo prebuild` and gitignored, so hand edits there are not durable.
// Services owned by a native module are declared in that module's own manifest.
const { AndroidConfig, withAndroidManifest } = require('expo/config-plugins');

const PERMISSIONS = [
  'android.permission.CALL_PHONE',
  'android.permission.MODIFY_AUDIO_SETTINGS',
  'android.permission.READ_CONTACTS',
  'android.permission.REQUEST_IGNORE_BATTERY_OPTIMIZATIONS',
  'android.permission.POST_NOTIFICATIONS',
];

const action = (name) => ({ $: { 'android:name': name } });

// Android only offers an app as "default phone app" if it handles ACTION_DIAL,
// both bare and with a tel: number.
const DIAL_FILTERS = [
  {
    action: [action('android.intent.action.DIAL')],
    category: [action('android.intent.category.DEFAULT')],
  },
  {
    action: [action('android.intent.action.DIAL'), action('android.intent.action.VIEW')],
    category: [action('android.intent.category.DEFAULT'), action('android.intent.category.BROWSABLE')],
    data: [{ $: { 'android:scheme': 'tel' } }],
  },
];

// Lets the app be chosen as the home screen, so the home button and a
// reboot always land on her tiles.
const HOME_FILTER = {
  action: [action('android.intent.action.MAIN')],
  category: [action('android.intent.category.HOME'), action('android.intent.category.DEFAULT')],
};

module.exports = function withMosterManifest(config) {
  config = AndroidConfig.Permissions.withPermissions(config, PERMISSIONS);

  return withAndroidManifest(config, (cfg) => {
    const main = AndroidConfig.Manifest.getMainActivityOrThrow(cfg.modResults);
    main['intent-filter'] = [...(main['intent-filter'] ?? []), ...DIAL_FILTERS, HOME_FILTER];
    return cfg;
  });
};
